<?php
namespace App\Application\Operations;
use App\Application\Audit\AuditWriter; use App\Application\Events\OutboxWriter; use App\Models\NotificationDelivery; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
final class NotificationDeliveryService { public function __construct(private AuditWriter $audit,private OutboxWriter $outbox){}
public function retry(NotificationDelivery $d):NotificationDelivery{return DB::transaction(function()use($d){$d=NotificationDelivery::whereKey($d->id)->lockForUpdate()->firstOrFail();if(!in_array($d->status,['FAILED','QUEUED'],true))throw ValidationException::withMessages(['status'=>__('wave8.notification_not_retryable')]);if($d->attempts >= $d->max_attempts){$d->update(['status'=>'DEAD_LETTERED']);return $d;}$attempt=$d->attempts+1;$d->update(['status'=>'QUEUED','attempts'=>$attempt,'next_attempt_at'=>now()->addMinutes(min(60,2**$attempt))]);DB::table('notification_attempts')->insert(['id'=>(string)Str::uuid(),'notification_delivery_id'=>$d->id,'attempt_number'=>$attempt,'status'=>'QUEUED','response'=>'{}','attempted_at'=>now()]);$this->audit->record('notification.retry.queued','notification_delivery',$d->id,['attempt'=>$attempt]);$this->outbox->record('notification.delivery.requested','notification_delivery',$d->id,['delivery_id'=>$d->id,'attempt'=>$attempt]);return $d->refresh();});}
public function cancel(NotificationDelivery $d):NotificationDelivery{if(!in_array($d->status,['QUEUED','FAILED'],true))throw ValidationException::withMessages(['status'=>__('wave8.notification_not_cancellable')]);$d->update(['status'=>'CANCELLED','next_attempt_at'=>null]);$this->audit->record('notification.cancelled','notification_delivery',$d->id,[]);return $d->refresh();}}
